-- ----------------------------
-- Table structure for constataciones_domiciliarias
-- ----------------------------
DROP TABLE IF EXISTS `constataciones_domiciliarias`;
CREATE TABLE `constataciones_domiciliarias`  (
  `id_constatacion` int NOT NULL AUTO_INCREMENT,
  `id_financiamiento` int NOT NULL,
  `tipo_usuario` tinyint NOT NULL COMMENT '1=conductor, 2=cliente',
  `id_tipo_usuario` int NOT NULL COMMENT 'ID del conductor o cliente según tipo_usuario',
  `foto_domicilio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ruta del archivo de foto',
  `departamento` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Departamento',
  `provincia` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Provincia',
  `distrito` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Distrito',
  `direccion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Dirección manual',
  `link_google_maps` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Link de Google Maps (opcional)',
  `captura_google_maps` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Captura de Google Maps (opcional)',
  `latitud` decimal(10, 8) NULL DEFAULT NULL COMMENT 'Coordenada de latitud (opcional)',
  `longitud` decimal(11, 8) NULL DEFAULT NULL COMMENT 'Coordenada de longitud (opcional)',
  `fecha_constatacion` datetime NOT NULL COMMENT 'Fecha y hora de la constatación',
  `observaciones` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Observaciones opcionales',
  `usuario_id` int NOT NULL COMMENT 'Usuario que realizó la constatación',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_constatacion`) USING BTREE,
  INDEX `usuario_id`(`usuario_id` ASC) USING BTREE,
  INDEX `idx_financiamiento`(`id_financiamiento` ASC) USING BTREE,
  INDEX `idx_tipo_usuario`(`tipo_usuario` ASC, `id_tipo_usuario` ASC) USING BTREE,
  INDEX `idx_fecha`(`fecha_constatacion` ASC) USING BTREE,
  CONSTRAINT `constataciones_domiciliarias_ibfk_1` FOREIGN KEY (`id_financiamiento`) REFERENCES `financiamiento` (`idfinanciamiento`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `constataciones_domiciliarias_ibfk_2` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`usuario_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

