  `idcuotas_financiamiento` int NOT NULL AUTO_INCREMENT,
  `id_financiamiento` int NOT NULL,
  `numero_cuota` int NOT NULL,
  `monto` decimal(10, 2) NOT NULL,
  `monto_cuota_base` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Monto original sin comisiones',
  `comision_canal_digital` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Comisión fija (0.50 soles o 0.20 dólares)',
  `descuento_aplicado` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Cuánto subsidió la empresa',
  `moneda_cuota` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'S/. o $',
  `mora` decimal(10, 2) NULL DEFAULT NULL,
  `fecha_vencimiento` date NOT NULL,
  `estado` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `fecha_pago` date NULL DEFAULT NULL,
  `estado_eliminado` tinyint(1) NULL DEFAULT 0,
  `puntos_aplicados` tinyint(1) NULL DEFAULT 0 COMMENT 'Indica si ya se aplicaron puntos por este pago',
  `penalizacion_perdonada` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Indica si la penalización por retraso fue perdonada (0=No, 1=Sí)',
  `fecha_perdon` timestamp NULL DEFAULT NULL COMMENT 'Fecha cuando se perdonó la penalización',
  `motivo_perdon` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Motivo del perdón de penalización',
  PRIMARY KEY (`idcuotas_financiamiento`) USING BTREE,
  INDEX `cuotaofFinance_idx`(`id_financiamiento` ASC) USING BTREE,
  INDEX `idx_puntos_aplicados`(`puntos_aplicados` ASC) USING BTREE,
  INDEX `idx_cuota_puntos`(`idcuotas_financiamiento` ASC, `puntos_aplicados` ASC) USING BTREE,
  INDEX `idx_id_financiamiento_estado`(`id_financiamiento` ASC, `estado` ASC, `estado_eliminado` ASC) USING BTREE,
  INDEX `idx_penalizacion_perdonada`(`penalizacion_perdonada` ASC) USING BTREE,
  CONSTRAINT `cuotaofFinance` FOREIGN KEY (`id_financiamiento`) REFERENCES `financiamiento` (`idfinanciamiento`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 40699 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

