  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `departamento_id` int NULL DEFAULT NULL COMMENT 'ID del departamento - NULL = disponible en todos',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cupones_activo`(`activo` ASC) USING BTREE,
  INDEX `idx_cupones_fechas`(`fecha_inicio` ASC, `fecha_fin` ASC) USING BTREE,
  INDEX `idx_departamento`(`departamento_id` ASC) USING BTREE,
  CONSTRAINT `fk_cupones_departamento` FOREIGN KEY (`departamento_id`) REFERENCES `depast` (`iddepast`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

