-- ----------------------------
-- Table structure for financiamiento
-- ----------------------------
DROP TABLE IF EXISTS `financiamiento`;
CREATE TABLE `financiamiento`  (
  `idfinanciamiento` int NOT NULL AUTO_INCREMENT,
  `id_conductor` int NULL DEFAULT NULL,
  `id_cliente` int NULL DEFAULT NULL,
  `idproductosv2` int NULL DEFAULT NULL,
  `id_coti` int NULL DEFAULT NULL,
  `usuario_id` int NULL DEFAULT NULL,
  `codigo_asociado` int NOT NULL,
  `grupo_financiamiento` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `nombre_personalizado` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `id_variante` int NULL DEFAULT NULL,
  `cantidad_producto` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `monto_total` decimal(10, 2) NOT NULL,
  `cuota_inicial` decimal(10, 2) NULL DEFAULT NULL,
  `cuotas` int NOT NULL,
  `estado` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `frecuencia` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `second_product` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `monto_inscrip` decimal(10, 2) NULL DEFAULT NULL,
  `monto_sin_interes` decimal(10, 2) NULL DEFAULT NULL,
  `moneda` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `monto_recalculado` decimal(10, 2) NULL DEFAULT NULL,
  `tasa` decimal(10, 2) NULL DEFAULT NULL,
  `aprobado` tinyint(1) NULL DEFAULT NULL,
  `estado_eliminado` tinyint(1) NULL DEFAULT 0,
  `incobrable` tinyint(1) NULL DEFAULT 0,
  `cobrar_mora` tinyint(1) NULL DEFAULT 1,
  `estado_entrega` enum('pendiente','entregado') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Estado de entrega del vehículo para CrediYango (NULL para otros planes)',
  `es_entrega_especial` tinyint(1) NULL DEFAULT 0 COMMENT 'Indica si es financiamiento especial con entrega de vehículo (plan 42)',
  `placa_vehiculo` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Placa del vehículo para mantenimiento (Plan IncaMotors ID 44)',
  `numero_corporativo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `fecha_entrega` date NULL DEFAULT NULL,
  `fecha_inicio_pagos_calculada` date NULL DEFAULT NULL,
  PRIMARY KEY (`idfinanciamiento`) USING BTREE,
  INDEX `FinanceOfConductor_idx`(`id_conductor` ASC) USING BTREE,
  INDEX `producFinance_idx`(`idproductosv2` ASC) USING BTREE,
  INDEX `idx_financ_conductor`(`id_conductor` ASC) USING BTREE,
  INDEX `idx_financ_cliente`(`id_cliente` ASC) USING BTREE,
  INDEX `idx_financiamiento_fecha_entrega`(`fecha_entrega` ASC) USING BTREE,
  INDEX `idx_financiamiento_fecha_inicio_pagos`(`fecha_inicio_pagos_calculada` ASC) USING BTREE,
  INDEX `idx_placa_vehiculo`(`placa_vehiculo` ASC) USING BTREE,
  CONSTRAINT `FinanceOfConductor` FOREIGN KEY (`id_conductor`) REFERENCES `conductores` (`id_conductor`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `producFinance` FOREIGN KEY (`idproductosv2`) REFERENCES `productosv2` (`idproductosv2`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE = InnoDB AUTO_INCREMENT = 712 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

