  `monto_original` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Monto original de la cuota sin descuento',
  `mora` decimal(10, 2) NULL DEFAULT 0.00 COMMENT 'Monto de mora incluido en el pago',
  `comision_asumida` decimal(10, 2) NULL DEFAULT 0.00 COMMENT 'Comisión que asumió la empresa (0.50 PEN o 0.20 USD)',
  `monto_recibido` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Monto real que recibió la empresa (monto - comision_asumida)',
  `numero_documento` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `periodo` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PAGADO',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_financiamiento`(`id_financiamiento` ASC) USING BTREE,
  INDEX `idx_cuota`(`id_cuota` ASC) USING BTREE,
  INDEX `idx_trace`(`numero_trace` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 645 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

