  `id` int NOT NULL AUTO_INCREMENT,
  `tipo_inscripcion` enum('conductor','cliente') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tipo de inscripción',
  `id_pago_inscripcion` int NULL DEFAULT NULL COMMENT 'FK a pagos_inscripcion (para conductores)',
  `id_cliente_pago` int NULL DEFAULT NULL COMMENT 'FK a cliente_pago (para clientes)',
  `cuotas_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'JSON con las cuotas pagadas (solo para financiados)',
  `id_usuario_registro` int NULL DEFAULT NULL COMMENT 'Usuario que registró el pago',
  `id_usuario_aprobacion` int NULL DEFAULT NULL COMMENT 'Usuario que aprobó el pago',
  `fecha_registro` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_aprobacion` timestamp NULL DEFAULT NULL,
  `estado` enum('pendiente','aprobado','rechazado') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pendiente',
  `observaciones` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tipo_inscripcion`(`tipo_inscripcion` ASC) USING BTREE,
  INDEX `idx_estado`(`estado` ASC) USING BTREE,
  INDEX `id_pago_inscripcion`(`id_pago_inscripcion` ASC) USING BTREE,
  INDEX `id_cliente_pago`(`id_cliente_pago` ASC) USING BTREE,
  INDEX `id_usuario_registro`(`id_usuario_registro` ASC) USING BTREE,
  INDEX `id_usuario_aprobacion`(`id_usuario_aprobacion` ASC) USING BTREE,
  CONSTRAINT `pagos_pendientes_inscripcion_ibfk_1` FOREIGN KEY (`id_pago_inscripcion`) REFERENCES `pagos_inscripcion` (`id_pago`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `pagos_pendientes_inscripcion_ibfk_2` FOREIGN KEY (`id_cliente_pago`) REFERENCES `cliente_pago` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `pagos_pendientes_inscripcion_ibfk_3` FOREIGN KEY (`id_usuario_registro`) REFERENCES `usuarios` (`usuario_id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `pagos_pendientes_inscripcion_ibfk_4` FOREIGN KEY (`id_usuario_aprobacion`) REFERENCES `usuarios` (`usuario_id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Pagos pendientes de aprobación para inscripciones' ROW_FORMAT = Dynamic;

