-- ----------------------------
-- View structure for view_cotizaciones
-- ----------------------------
DROP VIEW IF EXISTS `view_cotizaciones`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_cotizaciones` AS select `c`.`cotizacion_id` AS `cotizacion_id`,`c`.`numero` AS `numero`,`c`.`fecha` AS `fecha`,`c`.`moneda` AS `moneda`,`c`.`cm_tc` AS `cm_tc`,`c`.`id_tido` AS `id_tido`,concat(`cl`.`documento`,' | ',`cl`.`datos`) AS `documento`,`cl`.`datos` AS `datos`,`c`.`total` AS `total`,`c`.`estado` AS `estado`,`u`.`nombres` AS `vendedor` from (((`cotizaciones` `c` left join `documentos_sunat` `ds` on(`c`.`id_tido` = `ds`.`id_tido`)) left join `clientes` `cl` on(`c`.`id_cliente` = `cl`.`id_cliente`)) left join `usuarios` `u` on(`c`.`id_usuario` = `u`.`usuario_id`)) where `c`.`id_empresa` = '12' and `c`.`sucursal` = '1' and `c`.`estado` <> '2' order by `c`.`fecha` desc;

-- ----------------------------
