DROP VIEW IF EXISTS `view_productos_1`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_productos_1` AS select `p`.`id_producto` AS `id_producto`,`p`.`cod_barra` AS `cod_barra`,`p`.`descripcion` AS `descripcion`,`p`.`precio` AS `precio`,`p`.`costo` AS `costo`,`p`.`cantidad` AS `cantidad`,`p`.`iscbp` AS `iscbp`,`p`.`id_empresa` AS `id_empresa`,`p`.`sucursal` AS `sucursal`,`p`.`ultima_salida` AS `ultima_salida`,`p`.`codsunat` AS `codsunat`,`p`.`usar_barra` AS `usar_barra`,`p`.`precio_mayor` AS `precio_mayor`,`p`.`precio_menor` AS `precio_menor`,`p`.`razon_social` AS `razon_social`,`p`.`ruc` AS `ruc`,`p`.`estado` AS `estado`,`p`.`almacen` AS `almacen`,`p`.`precio2` AS `precio2`,`p`.`precio3` AS `precio3`,`p`.`precio4` AS `precio4`,`p`.`precio_unidad` AS `precio_unidad`,`p`.`codigo` AS `codigo` from `productos` `p` where `p`.`id_empresa` = 12 and `p`.`sucursal` = '1' and `p`.`estado` = '1' and `p`.`almacen` = '1' order by `p`.`id_producto` desc;

