DROP VIEW IF EXISTS `view_productos_2`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_productos_2` AS select `p`.`id_producto` AS `id_producto`,`p`.`cod_barra` AS `cod_barra`,`p`.`descripcion` AS `descripcion`,`p`.`precio` AS `precio`,`p`.`costo` AS `costo`,`p`.`cantidad` AS `cantidad`,`p`.`iscbp` AS `iscbp`,`p`.`id_empresa` AS `id_empresa`,`p`.`sucursal` AS `sucursal`,`p`.`ultima_salida` AS `ultima_salida`,`p`.`codsunat` AS `codsunat`,`p`.`usar_barra` AS `usar_barra`,`p`.`precio_mayor` AS `precio_mayor`,`p`.`precio_menor` AS `precio_menor`,`p`.`razon_social` AS `razon_social`,`p`.`ruc` AS `ruc`,`p`.`estado` AS `estado`,`p`.`almacen` AS `almacen`,`p`.`precio2` AS `precio2`,`p`.`precio3` AS `precio3`,`p`.`precio4` AS `precio4`,`p`.`precio_unidad` AS `precio_unidad`,`p`.`codigo` AS `codigo` from `productos` `p` where `p`.`id_empresa` = 12 and `p`.`sucursal` = '1' and `p`.`estado` = '1' and `p`.`almacen` = '2' order by `p`.`id_producto` desc;

-- ----------------------------
-- View structure for view_ventas
-- ----------------------------
DROP VIEW IF EXISTS `view_ventas`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY INVOKER VIEW `view_ventas` AS select `v`.`id_venta` AS `cod_v`,concat(`ds`.`abreviatura`,' | ',`v`.`serie`,' - ',`v`.`numero`) AS `sn_v`,concat(`c`.`documento`,' | ',`c`.`datos`) AS `datos_cl`,concat(if(`v`.`moneda` = 1,'S/ ','$ '),if(`v`.`apli_igv` = '1',`v`.`total` / (`v`.`igv` + 1),`v`.`total`)) AS `subtotal`,concat(if(`v`.`moneda` = 1,'S/ ','$ '),if(`v`.`apli_igv` = '1',`v`.`total` / (`v`.`igv` + 1) * `v`.`igv`,0)) AS `igv_v`,concat(`v`.`enviado_sunat`,'-',`v`.`id_tido`,'-',`v`.`id_venta`) AS `doc_ventae`,concat(`v`.`id_venta`,'--',ifnull(`vs`.`nombre_xml`,'-')) AS `id_venta`,`v`.`fecha_emision` AS `fecha_emision`,`ds`.`abreviatura` AS `abreviatura`,`v`.`apli_igv` AS `apli_igv`,`v`.`igv` AS `igv`,`v`.`id_tido` AS `id_tido`,`v`.`serie` AS `serie`,`v`.`numero` AS `numero`,`c`.`documento` AS `documento`,`c`.`datos` AS `datos`,concat(if(`v`.`moneda` = 1,'S/ ','$ '),`v`.`total`) AS `total`,`v`.`estado` AS `estado`,`v`.`enviado_sunat` AS `enviado_sunat`,ifnull(`vs`.`nombre_xml`,'-') AS `nombre_xml` from (((`ventas` `v` left join `documentos_sunat` `ds` on(`v`.`id_tido` = `ds`.`id_tido`)) left join `clientes` `c` on(`v`.`id_cliente` = `c`.`id_cliente`)) left join `ventas_sunat` `vs` on(`v`.`id_venta` = `vs`.`id_venta`)) where `v`.`id_empresa` = '12' and `v`.`sucursal` = '1' order by `v`.`fecha_emision`,`v`.`numero`;

-- ----------------------------
-- Triggers structure for table guia_remision
-- ----------------------------
DROP TRIGGER IF EXISTS `ti_guia_remision`;
delimiter ;;
CREATE TRIGGER `ti_guia_remision` AFTER INSERT ON `guia_remision` FOR EACH ROW BEGIN
DECLARE idtido_ INT;
DECLARE idempresa_ INT;
DECLARE sucursal_ INT;
SET idtido_ = 11;
SET idempresa_ = new.id_empresa;
SET sucursal_ = new.sucursal;
UPDATE documentos_empresas AS de
SET de.numero = de.numero + 1
WHERE de.id_empresa = idempresa_ AND de.id_tido = idtido_ AND de.sucursal=sucursal_;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table notas_electronicas
-- ----------------------------
DROP TRIGGER IF EXISTS `ti_notas_e`;
delimiter ;;
CREATE TRIGGER `ti_notas_e` AFTER INSERT ON `notas_electronicas` FOR EACH ROW BEGIN
  DECLARE idtido_ INT ;
  DECLARE idempresa_ INT ;
  DECLARE sucursal_ INT;
  
  
  SET idtido_ = new.tido ;
  SET idempresa_ = new.id_empresa ;
  SET sucursal_ = new.sucursal;
  
  UPDATE 
    documentos_empresas AS de 
  SET
    de.numero = de.numero + 1 
  WHERE de.id_empresa = idempresa_ 
    AND de.id_tido = idtido_ AND de.sucursal=sucursal_;
  
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table ventas
-- ----------------------------
DROP TRIGGER IF EXISTS `ti_ventas`;
delimiter ;;
CREATE TRIGGER `ti_ventas` AFTER INSERT ON `ventas` FOR EACH ROW BEGIN
DECLARE idtido_ INT;
DECLARE idempresa_ INT;
DECLARE idcliente_ INT;
DECLARE total_ FLOAT;
DECLARE fecha_ DATE;
DECLARE sucursal_ INT;
SET idtido_ = new.id_tido;
SET idempresa_ = new.id_empresa;
SET idcliente_ = new.id_cliente;
SET fecha_ = new.fecha_emision;
SET total_ = new.total;
SET sucursal_ = new.sucursal;
UPDATE documentos_empresas AS de 
SET de.numero = de.numero + 1 
WHERE de.id_empresa = idempresa_ AND de.id_tido = idtido_ AND sucursal = sucursal_;
UPDATE clientes AS c 
SET c.ultima_venta = fecha_, c.total_venta = c.total_venta + total_
WHERE c.id_cliente = idcliente_;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
