INSERT INTO `beneficios` VALUES (6, 'REDMI NOTE 14', 2, 0, 'Ahora puedes acceder al nuevo Redmi Note 14, un smartphone potente, confiable y perfecto para trabajar con el aplicativo sin interrupciones. 🚗💨\r\n💡 No dejes pasar esta oportunidad. Renueva tu celular y sigue creciendo con nosotros.', 200.00, 7, 100.00, NULL, NULL, NULL, NULL, 'img/beneficios/beneficio_1761231672_68fa43388fc5f.png', 1, '2025-09-28 19:13:25', '2025-10-23 10:01:12', NULL);
INSERT INTO `beneficios` VALUES (7, 'REDMI NOTE 14 PRO', 3, 0, 'Pensamos en el crecimiento de nuestros clientes, por eso ofrecemos el nuevo Redmi Note 14 pro, un equipo moderno y potente para que trabajes con total confianza. 🚗💨\r\n\r\n✅ Cuotas semanales accesibles\r\n\r\n💡 Aprovecha esta oportunidad y lleva tu celular.', 300.00, 7, 130.00, NULL, NULL, NULL, NULL, 'img/beneficios/beneficio_1761231708_68fa435c0c0d7.png', 1, '2025-09-28 19:22:05', '2025-10-23 10:01:48', NULL);
