INSERT INTO `beneficios` VALUES (17, 'CREDIMOTOS  S/4500', 22, 0, '🏍️ ¡Llévate tu moto con CrediMotos! 🔥\r\nOfrecemos un Certificado de CrediMotos con un valor de S/4500 por 58 semanas.\r\n💥 Pero si adelantas 15 semanas (S/1650), ¡te llevas tu moto de inmediato! 🙌\r\n\r\nTus cuotas quedan en solo S/110 semanales.\r\n🚀 ¡Fácil, rápido y con entrega asegurada!\r\n📲 Contáctanos y descubre lo sencillo que es tener tu moto con CrediGo.', 1650.00, 43, 110.00, 150.00, 'S/.', NULL, NULL, 'img/beneficios/beneficio_1765382733_69399a4d03d03.png', 1, '2025-10-21 10:27:39', '2025-12-10 10:05:33', NULL);
INSERT INTO `beneficios` VALUES (18, 'CREDIMOTOS S/5500', 22, 0, '🏍️ ¡Llévate tu moto con CrediMotos! 🔥\r\nOfrecemos un Certificado de CrediMotos con un valor de S/5500 por 58 semanas.\r\n💥 Pero si adelantas 15 semanas, ¡te llevas tu moto de inmediato! 🙌\r\nTus cuotas quedan en solo S/130 semanales.\r\n🚀 ¡Fácil, rápido y con entrega asegurada!\r\n📲 Contáctanos y descubre lo sencillo que es tener tu moto con CrediGo.', 1950.00, 43, 130.00, NULL, 'S/.', NULL, NULL, 'img/beneficios/beneficio_1765302216_69385fc8a5a68.png', 1, '2025-10-21 10:30:23', '2025-12-09 11:43:36', NULL);
