INSERT INTO `beneficios` VALUES (21, 'CREDIMOTOS S/8500', 22, 0, '🏍️ ¡Llévate tu moto con CrediMotos! 🔥\r\nOfrecemos un Certificado de CrediMotos con un valor de S/8500 por 58 semanas.\r\n💥 Pero si adelantas 15 semanas, ¡te llevas tu moto de inmediato! 🙌\r\nTus cuotas quedan en solo S/200 semanales.\r\n🚀 ¡Fácil, rápido y con entrega asegurada!\r\n📲 Contáctanos y descubre lo sencillo que es tener tu moto con CrediGo.', 3000.00, 43, 200.00, 200.00, 'S/.', NULL, NULL, 'img/beneficios/beneficio_1765302084_69385f4446bda.png', 1, '2025-10-21 10:35:29', '2025-12-09 11:41:43', NULL);
INSERT INTO `beneficios` VALUES (22, 'BATERIAS', 16, 0, '🔋 ¡Renueva tu batería con CrediGo! 🚗\r\nFinancia tu batería con solo el 30% de inicial 😎\r\nEl precio varía según la cotización.\r\nPara recibir la tuya, envíanos:\r\n📌 Marca del vehículo\r\n📌 Modelo\r\n📌 Año\r\n📌 Número de placa\r\n💬 Escríbenos y recibe la mejor opción para tu vehículo.', 70.00, 3, 60.00, NULL, 'S/.', NULL, NULL, 'img/beneficios/beneficio_1761061399_68f7aa170f6f7.png', 1, '2025-10-21 10:43:19', '2025-11-03 10:19:30', 8);
INSERT INTO `beneficios` VALUES (24, 'CHIP CORPORATIVO', 36, 0, '📲 ¡Activa tu Chip Corporativo con CrediGo! 🚀\r\nDisfruta de un plan ilimitado por solo S/35 mensuales 🔥\r\nIdeal para conductores que necesitan estar siempre conectados.', 5.00, 12, 35.00, NULL, 'S/.', NULL, NULL, 'img/beneficios/beneficio_1761061720_68f7ab58236c8.png', 1, '2025-10-21 10:48:40', '2025-10-29 15:18:36', NULL);
INSERT INTO `beneficios` VALUES (25, 'MANTENIMIENTO INCAMOTORS', 15, 0, '🚗 ¡Dale mantenimiento a tu vehículo con IncaMotors y CrediGo! 🔧\r\nAprovecha nuestro financiamiento con solo el 30% de inicial 💥\r\nY por esta promoción, te regalamos el filtro de aceite y el escaneo 🛠️\r\n\r\n💬 Agenda tu cita y mantén tu vehículo en perfectas condiciones con IncaMotors y CrediGo.', 72.00, 3, 56.00, NULL, 'S/.', NULL, NULL, 'img/beneficios/beneficio_1761082233_68f7fb79cdbc4.png', 1, '2025-10-21 10:54:30', '2025-10-29 15:18:15', 8);
INSERT INTO `beneficios` VALUES (26, 'LLANTAS', 14, 0, '¡Renueva tus llantas con CrediGo! 🚗\r\nFinancia tus llantas con solo el 30% de inicial 💥\r\nContamos con gran variedad de marcas y medidas para todo tipo de vehículo.\r\nEl precio varía según:\r\n📍 Medida\r\n📍 Cantidad\r\n📍 Marca y modelo del vehículo\r\n📍 Año\r\n📍 Calidad (económica o intermedia)\r\n💬 Solicita tu cotización personalizada y equípate con seguridad y estilo con CrediGo.', 89.00, 4, 51.50, NULL, 'S/.', NULL, NULL, 'img/beneficios/beneficio_1761062504_68f7ae6894ea4.png', 1, '2025-10-21 11:01:44', '2025-10-27 10:04:29', 8);
INSERT INTO `beneficios` VALUES (29, 'CREDI YANGO', 45, 0, '¡Tu carro te espera con Credi Yango! 🚗\r\nAccede con una inicial de solo $2000 y paga cómodamente $100 semanales por 200 semanas.\r\n🔥 ¡Así de simple, así de tuyo!', 2000.00, 200, 100.00, NULL, '$', NULL, NULL, 'img/beneficios/beneficio_1762806807_69124c17eb4f5.png', 1, '2025-11-04 09:37:53', '2025-11-10 14:33:27', NULL);
INSERT INTO `beneficios` VALUES (30, 'ACEITE MOTUL', 15, NULL, '🚗 ¡Manten tu motor como nuevo con Motul!\r\nAceite Motul 4L a S/180\r\n💸 Financiamos tu compra o paga al contado.\r\n¡No dejes pasar esta oportunidad!', 54.00, 3, 42.00, NULL, NULL, NULL, NULL, 'img/beneficios/beneficio_1762813061_69126485f1a5b.png', 1, '2025-11-10 16:17:41', '2025-11-10 16:17:41', 8);
INSERT INTO `beneficios` VALUES (31, 'AUTOMOTRIZ', 42, NULL, '🔧Atención especializada en: reparación de motores, suspensión, frenos, embrague, mantenimiento preventivo, planchado y pintura, y traccionamiento de compactos.\r\nTodos los servicios se realizan bajo evaluación previa en el taller para brindar una cotización exacta y personalizada.', 50.00, 3, 30.00, NULL, 'S/.', NULL, 'semanal', 'img/beneficios/beneficio_1764184789_692752d5c4058.png', 1, '2025-11-26 13:19:49', '2025-11-26 13:19:49', 8);
